gb2Q(){return"\u0647\u0630\u0647 \u0644\u064a\u0633\u062a \u0628\u0637\u0627\u0642\u0629 \u0645\u0648\u0638\u0641. \u0627\u0645\u0633\u062d \u0631\u0645\u0632 QR \u0627\u0644\u0645\u0648\u062c\u0648\u062f \u0639\u0644\u0649 \u0648\u062c\u0647 \u0627\u0644\u0628\u0637\u0627\u0642\u0629."},
gb2V(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0628\u0637\u0627\u0642\u0629 \u0645\u0637\u0627\u0628\u0642\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u0631\u0645\u0632. \u0642\u062f \u062a\u0643\u0648\u0646 \u062a\u0627\u0628\u0639\u0629 \u0644\u0646\u0638\u0627\u0645 \u0622\u062e\u0631 \u0623\u0648 \u0644\u0645 \u062a\u064f\u0635\u062f\u0631 \u0645\u0646 \u0647\u0646\u0627."},
gb2M(){return"\u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632. \u0623\u062f\u062e\u0644 \u0631\u0642\u0645 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0628\u0627\u0644\u0623\u0633\u0641\u0644 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u0630\u0644\u0643."},
gb2L(){return"\u0644\u0645 \u064a\u0628\u062f\u0623 \u0627\u0644\u0645\u0627\u0633\u062d \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u062d\u062f\u062f. \u0639\u0644\u0649 \u0627\u0644\u0648\u064a\u0628 \u064a\u062a\u0645 \u062a\u0646\u0632\u064a\u0644 \u0645\u0643\u062a\u0628\u0629 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0631\u0645\u0648\u0632 \u0642\u0628\u0644 \u0641\u062a\u062d \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627\u060c \u0648\u063a\u0627\u0644\u0628\u064b\u0627 \u0645\u0627 \u064a\u0639\u0646\u064a \u0630\u0644\u0643 \u0623\u0646 \u0627\u0644\u062a\u0646\u0632\u064a\u0644 \u0642\u062f \u062d\u064f\u0638\u0631. \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0648\u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629\u060c \u0623\u0648 \u0623\u062f\u062e\u0644 \u0631\u0642\u0645 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0628\u0627\u0644\u0623\u0633\u0641\u0644."},
gb2S(){return"\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629"},
gb2K(){return"\u062a\u0645 \u0631\u0641\u0636 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627. \u0627\u0633\u0645\u062d \u0628\u0630\u0644\u0643 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0645\u062a\u0635\u0641\u062d \u0623\u0648 \u0627\u0644\u062c\u0647\u0627\u0632\u060c \u0623\u0648 \u0623\u062f\u062e\u0644 \u0631\u0642\u0645 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0628\u0627\u0644\u0623\u0633\u0641\u0644."},
gb2U(){return"\u0627\u0644\u0625\u0636\u0627\u0621\u0629"},
