gb30(){return"\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0648\u0638\u0641"},
gb1U(){return"\u0633\u0627\u0631\u064a\u0629"},
gb1N(){return"\u0644\u0627 \u064a\u064f\u0633\u0645\u062d \u0628\u0627\u0644\u062f\u062e\u0648\u0644"},
b1Q(a){return"\u0647\u0630\u0647 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u063a\u064a\u0631 \u0633\u0627\u0631\u064a\u0629 \u0642\u0628\u0644 "+a+"."},
b1P(a){return"\u062a\u0646\u062a\u0647\u064a \u062e\u0644\u0627\u0644 "+a+" \u064a\u0648\u0645\u064b\u0627."},
b1O(a){return"\u0627\u0646\u062a\u0647\u062a \u0641\u064a "+a+"."},
b1V(a){return"\u0633\u0627\u0631\u064a\u0629 \u062d\u062a\u0649 "+a+"."},
gb1T(){return"\u0647\u0630\u0627 \u0627\u0644\u0634\u062e\u0635 \u0644\u0645 \u064a\u0639\u062f \u0639\u0644\u0649 \u0631\u0623\u0633 \u0627\u0644\u0639\u0645\u0644. \u0644\u0627 \u064a\u064f\u0633\u0645\u062d \u0628\u0627\u0644\u062f\u062e\u0648\u0644 \u0631\u063a\u0645 \u0623\u0646 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0633\u0627\u0631\u064a\u0629."},
