gb2W(){return"\u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u0645\u0645\u0633\u0648\u062d\u0629"},
gb2D(){return"\u0625\u0638\u0647\u0627\u0631 \u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0642\u0648\u0645\u064a"},
gb2r(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0627\u062a\u0635\u0627\u0644. \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0634\u0628\u0643\u0629 \u0648\u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649."},
ga8P(){return"\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631"},
gb_4(){return"\u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0644\u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u0648\u0638\u0641\u064a\u0646\u060c \u0623\u0648 \u062a\u0628\u062f\u064a\u0644 \u0641\u0631\u064a\u0642\u064a \u0645\u062f\u064a\u0631\u064a\u0646 \u0645\u0628\u0627\u0634\u0631\u064a\u0646"},
gaqF(){return"\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0645\u062a\u0627\u062d\u0629 \u0644\u0644\u0645\u0648\u0627\u0631\u062f \u0627\u0644\u0628\u0634\u0631\u064a\u0629 \u0641\u0642\u0637."},
gaZV(){return"\u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631"},
gb_3(){return"\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0645\u062f\u064a\u0631\u064a\u0646 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u064a\u0646"},
gaZT(){return"\u0627\u062e\u062a\u0631 \u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0627\u0644\u062d\u0627\u0644\u064a\u060c \u0648\u062d\u062f\u062f \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u0627\u0644\u0645\u0631\u0627\u062f \u0646\u0642\u0644\u0647\u0645\u060c \u062b\u0645 \u0627\u062e\u062a\u0631 \u0645\u062f\u064a\u0631\u0647\u0645 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0627\u0644\u062c\u062f\u064a\u062f."},
gb_0(){return"\u0627\u062e\u062a\u0631 \u0645\u062f\u064a\u0631\u064a\u0646 \u0645\u0628\u0627\u0634\u0631\u064a\u0646 \u0644\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u0627\u0644\u062a\u0627\u0628\u0639\u064a\u0646 \u0644\u0647\u0645\u0627. \u064a\u0628\u0642\u0649 \u0627\u0644\u0645\u062f\u064a\u0631\u0627\u0646 \u0646\u0641\u0633\u064a\u0647\u0645\u0627 \u062a\u062d\u062a \u0645\u062f\u064a\u0631\u064a\u0647\u0645\u0627 \u0627\u0644\u062d\u0627\u0644\u064a\u064a\u0646."},
gaZE(){return"\u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0627\u0644\u062d\u0627\u0644\u064a"},
gaZP(){return"\u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0627\u0644\u062c\u062f\u064a\u062f"},
gaZO(){return"\u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0627\u0644\u0623\u0648\u0644"},
gaZX(){return"\u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0627\u0644\u062b\u0627\u0646\u064a"},
gaZW(){return"\u0627\u0628\u062d\u062b \u0628\u0627\u0644\u0627\u0633\u0645 \u0623\u0648 \u0627\u0644\u0643\u0648\u062f"},
gaZR(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0648\u0638\u0641\u0648\u0646 \u0645\u0637\u0627\u0628\u0642\u0648\u0646"},
gaZC(){return"\u062a\u063a\u064a\u064a\u0631"},
gaZQ(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0648\u0638\u0641\u0648\u0646 \u062a\u0627\u0628\u0639\u0648\u0646 \u0646\u0634\u0637\u0648\u0646"},
gaZY(){return"\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0643\u0644"},
aZZ(a,b){return"\u062a\u0645 \u062a\u062d\u062f\u064a\u062f "+a+" \u0645\u0646 "+b},
