aqD(a,b,c){return"\u0633\u064a\u062a\u0645 \u0646\u0642\u0644 "+a+" \u0645\u0648\u0638\u0641 \u0645\u0646 "+b+" \u0625\u0644\u0649 "+c+"."},
b_2(a,b,c,d){return"\u0633\u064a\u062a\u0645 \u0646\u0642\u0644 "+a+" \u0645\u0648\u0638\u0641 \u0645\u0646 \u0641\u0631\u064a\u0642 "+b+" \u0625\u0644\u0649 "+d+"\u060c \u0648\u0646\u0642\u0644 "+c+" \u0645\u0648\u0638\u0641 \u0645\u0646 \u0641\u0631\u064a\u0642 "+d+" \u0625\u0644\u0649 "+b+"."},
gaZD(){return"\u0644\u0646 \u062a\u062a\u063a\u064a\u0631 \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0642\u0629 \u0648\u0644\u0627 \u0627\u0644\u062c\u062f\u0627\u0648\u0644 \u0627\u0644\u062d\u0627\u0644\u064a\u0629\u061b \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0641\u0642\u0637 \u0633\u062a\u062a\u0628\u0639 \u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0627\u0644\u062c\u062f\u064a\u062f."},
gaqC(){return"\u0646\u0642\u0644 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646"},
gaZS(){return"\u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u061f"},
gaqE(){return"\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0641\u0631\u064a\u0642\u064a\u0646"},
gb__(){return"\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0641\u0631\u064a\u0642\u064a\u0646\u061f"},
